sys_script_include.script:
var returnTheRequest = Class.create();
returnTheRequest.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

	needMoreDetailedInfo: function() {
		var sysId = this.getParameter('sysparm_sys_id');
		var reqItem = new GlideRecord('sc_req_item');
		reqItem.get(sysId);
		reqItem.state = 12;
		reqItem.update();
		var task = new GlideRecord('sc_task');
		task.initialize();
		task.short_description = 'More info for your request';
		task.description = 'The request need more infomation. Please modify the details via below link:\n\n' + 
		'https://dev296769.service-now.com/sp?id=sc_cat_item&sys_id=&catitem_id=' + sysId;
		gs.error('includeddd:' + reqItem.requested_for);
		task.assigned_to = reqItem.requested_for;
		gs.error('assigned_to:' + task.assigned_to);
		task.task_type = 'task';
		task.insert();
		return 'OK';
	},
    type: 'returnTheRequest'
});
